`include "../aes_include.v"
`timescale 1ns/1ps

module tb_sbox;

	reg  [7:0] data_in;
	wire [7:0] data_out_e;
	wire [7:0] data_out_d;


	bSbox sbox_e(data_in, `ENCRIPT, data_out_e);
	bSbox sbox_e(data_out_e, `DECRIPT, data_out_d);


	initial begin
		data_in = 8'h01;

		#10;
		data_in = 8'h10;

		#10;
		data_in = 8'h02;

		#10;
		$finish;

	end	
endmodule

