19	//////////////////////////////////////////////////////////////////////////////////
20	`include "ve_AES_types.sv"
21	class AesCore extends BaseUnit;
22	
23		int BC, KC, ROUNDS;
24	
25		AlreadyComputed computed_val;
26		extern function new(string name, int id, ref AlreadyComputed com_val);
27		extern function word8 mul(word8 a, word8 b);
28		extern function void MixColumn(ref word8 a[4][`MAXBC]);
29		extern function void InvMixColumn(ref word8 a[4][`MAXBC]);
30		extern function void AddRoundKey(word8 rk[4][`MAXBC], ref word8 a[4][`MAXBC]);
31		extern function void SubBytes(word8 box[256], ref word8 a[4][`MAXBC]);
32		extern function void ShiftRows(word8 d, ref word8 a[4][`MAXBC]);
33		extern function int KeyExpansion(word8 k[4][`MAXBC], ref word8 W[`MAXROUNDS + 1][4][`MAXBC]);
34		extern function int Encrypt ( ref word8 a[4][`MAXBC], ref word8 rk[`MAXROUNDS + 1][4][`MAXBC]);
35		extern function int Decrypt ( ref word8 a[4][`MAXBC],ref  word8 rk[`MAXROUNDS + 1][4][`MAXBC]);
36		extern task run();
37		
38	endclass : AesCore
39	
40	function AesCore :: new(string name, int id, ref AlreadyComputed com_val);
41		super.new(name,id);
42		if(com_val == null) begin
43	         com_val = new();
44	    end
45		this.computed_val = com_val;
46	endfunction : new
47	
48	function word8 AesCore :: mul(word8 a, word8 b); 
49		word32 temp;
50		word8 val;
51		if (a && b) begin 
52			//temp = computed_val.Alogtable[(computed_val.Logtable[a] + computed_val.Logtable[b]) % 255];
53			temp = (computed_val.Logtable[a] + computed_val.Logtable[b]) % 255;
54			val =  computed_val.Alogtable[temp];
55		end 
56		else begin
57			temp = 0;
58		end
59		return val;
60	endfunction : mul
61	
62	function void AesCore :: AddRoundKey(word8 rk[4][`MAXBC], ref word8 a[4][`MAXBC]);
63		//XOR with the corresponding text from input
64		for (int i = 0; i < 4; i++) begin
65			for (int j = 0; j < BC; j++) begin
66				a[i][j] = a[i][j] ^ rk[i][j];
67			end
68		end
69	endfunction : AddRoundKey
70	
71	function void AesCore :: SubBytes(word8 box[256], ref word8 a[4][`MAXBC]);
72		//Every byte from current State is replaced with the value from Sbox 
73		for (int i = 0; i < 4; i++) begin
74			for (int j = 0; j < BC; j++) begin
75				a[i][j] = box [a[i][j]];
76			end
77		end
78		
79	endfunction : SubBytes
80	
81	function void AesCore :: ShiftRows( word8 d, ref word8 a[4][`MAXBC]);
82		// d is encryption
83		word8 tmp[`MAXBC];
84		int i, j;
85		
86		if (d == 0) begin
87	
88			for ( i = 1; i < 4; i++) begin
89			
90				for ( j = 0; j < BC; j++) begin
91					tmp [j] = a[i][(j + computed_val.shifts[BC - 4][i]) % BC ];
92				end	
93				for ( j = 0; j < BC; j++) begin
94					a[i][j] = tmp[j];
95				end		
96				
97			end	
98		end
99		else begin
100			for ( i = 1; i < 4; i++) begin
101				for ( j = 0; j < BC; j++) begin
102					tmp [j] = a[i][(BC + j - computed_val.shifts[BC - 4][i]) % BC ];
103				end	
104				for ( j = 0; j < BC; j++) begin
105					a[i][j] = tmp[j];
106				end		
107			end
108		end
109	endfunction : ShiftRows
110	
111	function void AesCore :: MixColumn(ref word8 a[4][`MAXBC]);
112		// The byte of every column are mixed in a linear way
113		// Equation is
114		// 2 3 1 1 * a0
115		// 1 2 3 1	 a1
116		// 1 1 2 3   a2
117		// 3 1 1 2   a3
118		word8 res [4][`MAXBC];
119		
120		int i, j;
121		
122		for(j = 0; j < BC; j++) begin
123			for (i = 0; i < 4; i++)	begin
124				res[i][j] = mul(2, a[i][j])
125					^ mul(3, a[(i+1) % 4][j])
126					^ a[(i + 2) % 4][j]
127					^ a[(i + 3) % 4][j];
128			end
129		end
130	
131		for(i = 0; i < 4; i++) begin
132			for( j = 0; j < 4; j++) begin
133				a[i][j] = res[i][j];
134			end
135		end
136		
137	endfunction : MixColumn
138	
139	function void AesCore :: InvMixColumn(ref word8 a[4][`MAXBC]);
140		// Decryption MixColumn
141		// Equation is
142		// 0x0e 0x0b 0x0d 0x09 * a0
143		// 0x09 0x0e 0x0b 0x0d	 a1
144		// 0x0d 0x09 0x0e 0x0b   a2
145		// 0x0b 0x0d 0x09 0x0e   a3
146		word8 res [4][`MAXBC];
147		int i, j;
148		
149		for(j = 0; j < BC; j++) begin
150			for (i = 0; i < 4; i++)	begin
151				res[i][j] = mul(8'h0E, a[i][j])
152					^ mul(8'h0B, a[(i+1) % 4][j])
153					^ mul(8'h0D, a[(i+2) % 4][j])
154					^ mul(8'h09, a[(i+3) % 4][j]);
155			end
156		end
157	
158		for(i = 0; i < 4; i++) begin
159			for( j = 0; j < 4; j++) begin
160				a[i][j] = res[i][j];
161			end
162		end
163		
164	endfunction : InvMixColumn
165	
166	function int AesCore :: KeyExpansion(word8 k[4][`MAXBC], ref word8 W[`MAXROUNDS + 1][4][`MAXBC]);
167		int i, j, t, RCpointer = 1;
168		word8 tk[4][`MAXKC];
169		
170		for (j = 0; j < KC; j++) begin
171			for(i = 0; i < 4; i++) begin
172				tk[i][j] = k[i][j];
173			end	
174		end
175		
176		t = 0;
177		// prepare values into round key array
178		
179		for (j = 0; (j < KC) && (t < (ROUNDS + 1)*BC); j++, t++) begin
180			for (i = 0; i < 4; i++) begin 
181				W[t/BC][i][t % BC] = tk[i][j];
182			end	
183		end
184		$display("t = %0d", t);	
185		while (t < (ROUNDS + 1) * BC) begin
186		
187			//function g non liniar 4 bytes input 
188			for (i = 0; i < 4; i++) begin
189				tk[i][0] = tk[i][0] ^ computed_val.S[tk[(i+1) % 4][KC -1]];
190			end
191			
192			tk[0][0] = tk[0][0] ^ computed_val.RC[RCpointer++];
193			//
194			
195			if (KC <= 6) begin
196				for( j = 1; j < KC; j++) begin
197					for (i = 0; i < 4; i++) begin
198						tk[i][j] = tk[i][j] ^ tk[i][j-1];
199					end
200				end
201			end
202			
203			else begin
204				for (j = 1; j < 4; j++) begin
205					for (i = 0; i < 4; i++) begin
206						tk[i][j] = tk[i][j] ^ tk[i][j-1];
207					end
208				end
209				for (i = 0; i < 4; i++) begin
210					tk[i][4] = tk[i][4] ^ computed_val.S[tk[i][3]];
211				end
212				for (j = 5; j < KC; j++) begin
213					tk[i][j] = tk[i][j] ^ tk[i][j-1];
214				end			
215			end	
216			
217			for (j = 0; (j < KC) && (t < (ROUNDS + 1)*BC); j++, t++) begin
218				for (i = 0; i < 4; i++) begin
219					W[t/BC][i][t%BC] = tk[i][j];
220				end
221			end
222				
223		end	
224		return 0;
225	endfunction : KeyExpansion
226	
227	function int AesCore :: Encrypt ( ref word8 a[4][`MAXBC],ref  word8 rk[`MAXROUNDS + 1][4][`MAXBC]);
228	 	int r;
229		AddRoundKey(rk[0], a);
230		
231		for(r = 1; r < ROUNDS; r++) begin
232			SubBytes(computed_val.S, a);
233			ShiftRows(0, a);
234			MixColumn(a);
235			AddRoundKey(rk[r], a);
236		end 
237	
238		SubBytes(computed_val.S, a);
239	 	ShiftRows(0, a);
240		AddRoundKey(rk[ROUNDS], a); 
241		
242		return 0;
243	endfunction : Encrypt
244	
245	function int AesCore :: Decrypt ( ref word8 a[4][`MAXBC],ref  word8 rk[`MAXROUNDS + 1][4][`MAXBC]);
246		int r;
247		// for decryption methods, apply the operation in oposite order 
248		AddRoundKey(rk[ROUNDS], a);
249		SubBytes(computed_val.Si, a);
250		ShiftRows(1,a);
251		 
252		for (r = ROUNDS -1; r > 0; r--) begin
253			AddRoundKey(rk[r], a);
254			InvMixColumn(a);
255			SubBytes(computed_val.Si, a);
256			ShiftRows(1, a);
257		end
258		
259		AddRoundKey(rk[0], a);
260	endfunction : Decrypt
261	
262	task AesCore :: run();
263		int i, j;
264		
265		word8 a[4][`MAXBC], rk[`MAXROUNDS + 1][4][`MAXBC], sk[4][`MAXKC];
266		
267		BC = 4;
268		KC = 4;
269		ROUNDS = computed_val.numrounds[KC-4][BC-4];
270		for ( i = 0; i < BC; i++) begin
271			for (j = 0; j < BC; j++) begin
272				a[i][j] = i;
273			end		
274		end
275		
276		for (j = 0; j < KC; j++) begin
277			for ( i = 0; i < 4; i++) begin
278				sk[i][j] = 0;
279			end		
280		end
281		
282		$display("\nPlainText ");
283		for (j = 0; j < BC; j++) begin
284			for ( i = 0; i < BC; i++) begin
285				$write("%0h", a[i][j]);
286			end
287		end
288		
289		KeyExpansion(sk, rk);
290		MixColumn(a);
291		
292		// Encrypt(a, rk);
293		$display("\nCipher ");
294		for (j = 0; j < BC; j++) begin
295			for ( i = 0; i < BC; i++) begin
296				$write("%0h", a[i][j]);
297			end
298		end
299		/*
300		Encrypt(a, rk);
301		
302		$display("\nCipher ");
303		for (j = 0; j < BC; j++) begin
304			for ( i = 0; i < BC; i++) begin
305				$write("%0h", a[i][j]);
306			end
307		end
308		Decrypt(a, rk);
309		Decrypt(a, rk);
310		
311		$display("\nCipher Decrypt");
312		for (j = 0; j < BC; j++) begin
313			for ( i = 0; i < BC; i++) begin
314				$write("%0h", a[i][j]);
315			end
316		end */
317		#10;
318	endtask : run

